/* Item card (potions, food, talismans, tokens, crates ...). Same look as the Mount and Glider cards. Position comes inline from Module:Consumable. */
.aa-item {
  display: flow-root;
  position: relative;
  box-sizing: border-box;
  width: 300px;
  max-width: 100%;
  padding: 10px 12px;
  background: linear-gradient(to bottom, rgba(24, 28, 38, 0.97), rgba(10, 12, 18, 0.97));
  border: 1px solid #5a5040;
  border-radius: 3px;
  box-shadow: 0 0 0 1px #000, 0 4px 12px rgba(0, 0, 0, 0.6);
  margin: 0 0 0.5em 0;
  color: #e8e4d8;
  font-size: 13px;
  line-height: 1.5;
  text-align: left;
}
.aa-item-head {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-bottom: 6px;
}
.aa-item-icon {
  line-height: 0;
}
.aa-item-title {
  display: flex;
  flex-direction: column;
  line-height: 1.3;
}
.aa-item-cat {
  color: #e8e4d8;
}
.aa-item-grade {
  font-size: 13px;
}
.aa-item-name {
  font-size: 16px;
  font-weight: bold;
}
.aa-item-sep {
  height: 1px;
  margin: 6px 0;
  background: linear-gradient(to right, transparent, #6a5d48, transparent);
}
.aa-item-line {
  color: #e8e4d8;
}
.aa-item-desc {
  margin-top: 4px;
  color: #e8e4d8;
}
/* a blank line in the description */
.aa-item-gap {
  margin-top: 0.7em;
}
.aa-item-label {
  margin-top: 10px;
  color: #8a8478;
}
.aa-item-green {
  color: #9acd32;
}

/* Cannot Sell */
.aa-item-nosell {
  margin-top: 10px;
  color: #d9423a;
}
/* A card floated to the right opens skill boxes (pets) towards the left, so they stay on the screen */
.aa-item-right .aa-mskill-tip {
  left: auto;
  right: 0;
}

/* Phones: a floated card gets its own line instead of squeezing the text */
@media (max-width: 500px) {
  .aa-item-float {
    float: none !important;
    clear: both !important;
    margin: 0 0 0.5em 0 !important;
  }
  /* skill hover boxes (pets) become a panel at the bottom of the screen (tap a skill to open) */
  .aa-item .aa-mskill-tip {
    position: fixed;
    left: 0.5em;
    right: 0.5em;
    top: auto;
    bottom: 0.5em;
    width: auto;
    max-height: 60vh;
    overflow-y: auto;
    margin-top: 0;
  }
}
